<script setup lang="ts">import{computed,onBeforeUnmount,ref}from'vue';import{useRouter}from'vue-router';import{ApiError}from'@career-launch/api-client';import{repository}from'../../services/repository';import{useSessionStore}from'../../stores/session';import{validateEmail,validateVerificationCode}from'./validation';const session=useSessionStore();const router=useRouter();const email=ref('student@example.com');const code=ref('');const sent=ref(false);const busy=ref(false);const error=ref('');const countdown=ref(0);let timer:number|undefined;const canSend=computed(()=>countdown.value===0);async function send(){error.value=validateEmail(email.value)??'';if(error.value)return;busy.value=true;try{await repository.auth.requestCode(email.value);sent.value=true;countdown.value=60;timer=window.setInterval(()=>{countdown.value--;if(countdown.value<=0&&timer)window.clearInterval(timer)},1000)}catch(value){error.value=value instanceof Error?value.message:'验证码发送失败'}finally{busy.value=false}}async function verify(){error.value=validateEmail(email.value)??validateVerificationCode(code.value)??'';if(error.value)return;busy.value=true;try{const user=await repository.auth.verifyCode(email.value,code.value);session.signedIn(user);const target=session.returnTo;session.returnTo=null;await router.push(target??'/')}catch(value){error.value=value instanceof ApiError?value.message:'登录失败，请重试'}finally{busy.value=false}}onBeforeUnmount(()=>{if(timer)window.clearInterval(timer)})</script>
<template><div v-if="session.loginVisible" class="dialog-layer" role="presentation" @mousedown.self="session.loginVisible=false"><section role="dialog" aria-modal="true" aria-labelledby="login-title"><button class="close" aria-label="关闭登录" @click="session.loginVisible=false">×</button><p class="brand">启程校招</p><h2 id="login-title">登录后继续</h2><p class="intro">保存心仪职位、管理投递进度和制作简历。登录后将回到你刚才想看的页面。</p><label>邮箱<input v-model="email" type="email" autocomplete="email"/></label><button class="code-button" type="button" :disabled="!canSend||busy" @click="send">{{countdown?`${countdown}s 后重发`:'发送验证码'}}</button><template v-if="sent"><label>验证码<input v-model="code" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/></label><p class="demo-tip">演示环境验证码：<strong>246810</strong></p></template><p v-if="error" class="error" role="alert">{{error}}</p><button class="cl-primary-button submit" type="button" :disabled="busy" @click="sent?verify():send()">{{busy?'请稍候…':sent?'登录':'获取验证码'}}</button><small>继续即表示你已阅读并同意服务条款与隐私说明。</small></section></div></template>
<style scoped>.dialog-layer{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:18px;background:rgba(7,15,31,.56);backdrop-filter:blur(6px)}section{position:relative;width:min(100%,410px);padding:30px;border-radius:18px;color:var(--cl-text);background:var(--cl-surface);box-shadow:var(--cl-shadow-float)}.close{position:absolute;top:14px;right:14px;width:36px;height:36px;border:0;border-radius:50%;color:var(--cl-muted);background:var(--cl-canvas);font-size:22px}.brand{margin-bottom:8px;color:var(--cl-primary);font-weight:800}h2{margin:0;color:var(--cl-text-strong);font-size:28px}.intro{margin:6px 0 22px;color:var(--cl-muted)}label{display:grid;gap:6px;margin-top:14px;font-weight:700}input{height:44px;padding:0 12px;border:1px solid var(--cl-border-strong);border-radius:8px;color:var(--cl-text);background:var(--cl-canvas)}.code-button{margin-top:8px;border:0;color:var(--cl-primary);background:none}.demo-tip{margin:8px 0;color:var(--cl-muted);font-size:13px}.error{margin:10px 0 0;color:var(--cl-danger)}.submit{width:100%;margin-top:18px}section>small{display:block;margin-top:14px;color:var(--cl-subtle);text-align:center}</style>
